using System;using System.IO;using ScoreModern.RecoveredFragments;
class InputAttachedMarkProof {static int Main(string[] a){try{byte[] before=File.ReadAllBytes(a[0]),after=File.ReadAllBytes(a[1]);int n=0,checks=0,changed=0;while(n*60+60<=before.Length&&BitConverter.ToSingle(before,n*60)!=0){for(int p=0;p<15;p++){int at=n*60+p*4;float value=BitConverter.ToSingle(before,at);if(p==10&&BitConverter.ToSingle(before,n*60)==1){value=InputAttachedMarks.DefaultValue(int.Parse(a[2]),BitConverter.ToSingle(before,n*60+12),BitConverter.ToSingle(before,n*60+16));changed++;}if(BitConverter.ToInt32(BitConverter.GetBytes(value),0)!=BitConverter.ToInt32(after,at))throw new Exception("Record "+n+" P"+(p+1));checks++;}n++;}if(BitConverter.ToSingle(after,n*60)!=0)throw new Exception("Record count");Console.WriteLine("PASS "+checks+" original mark parameter words; "+changed+" attached marks.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}
